-- Cleanup script for TGFITE/TGFVOA/TGFVOL - Refriparts
-- Generated by mapping canonical units to <=2-character codes when available.

--CREATE TABLE TGFVOL_BKP AS
--SELECT * FROM TGFVOL;
--
--CREATE TABLE TGFVOA_BKP AS
--SELECT * FROM TGFVOA;


PROMPT Iniciando normalização de unidades (TGFITE -> TGFVOA -> TGFVOL)
WHENEVER SQLERROR EXIT ROLLBACK;
SET DEFINE OFF;

BEGIN
  NULL;
END;
/

ALTER TRIGGER TRG_INC_UPD_TGFITE DISABLE;

-- 0) Atualiza TGFPRO.CODVOL para a sigla canônica
--UPDATE TGFPRO SET CODVOL = 'CD' WHERE CODVOL IN ('CDA');
UPDATE TGFPRO SET CODVOL = 'CX' WHERE CODVOL IN ('CX5000', 'CXA', 'CX1', 'CAIXA');
UPDATE TGFPRO SET CODVOL = 'KG' WHERE CODVOL IN ('KLG', 'KG/1', 'KG1','1 KG');
UPDATE TGFPRO SET CODVOL = 'LT' WHERE CODVOL IN ('L', 'LITRO');
UPDATE TGFPRO SET CODVOL = 'PC' WHERE CODVOL IN ('PEC', 'PÇ', 'PÇ.', 'PECA', 'PEÇA', 'PC/1', 'PC01PC', 'PC1', 'PCA', 'PCS', 'PEÇ', 'PE', 'PC.','PC0','PC0001','PC01');
UPDATE TGFPRO SET CODVOL = 'UN' WHERE CODVOL IN ('..UN','1 UNID', 'UND', 'UNI', 'UNID', 'UNIDA', 'UNIDAD', 'UN1', 'UN.','UN,', 'U', 'UN/1', 'UND.' , 'UNID.', 'UNN', 'U.N','UM','UN0001','UN0012','UN9','UND8','UND9','UNDI', 'UN''');
UPDATE TGFPRO SET CODVOL = 'MT' WHERE CODVOL IN ('M', 'METRO', 'MTS');
UPDATE TGFPRO SET CODVOL = 'PT' WHERE CODVOL IN ('PCT', 'PACOTE', 'PAC', 'PCT.', 'PCTE');
UPDATE TGFPRO SET CODVOL = 'TN' WHERE CODVOL IN ('TO', 'TON');
UPDATE TGFPRO SET CODVOL = 'RL' WHERE CODVOL IN ('RLRL', 'RLO', 'ROL', 'ROLO', 'RL1');
UPDATE TGFPRO SET CODVOL = 'BL' WHERE CODVOL IN ('BLOCO');
UPDATE TGFPRO SET CODVOL = 'FR' WHERE CODVOL IN ('FRASCO', 'FR1', 'FR/1');
UPDATE TGFPRO SET CODVOL = 'JG' WHERE CODVOL IN ('JOGO', 'JGO', 'JG1','JGO8','JGO9', 'JOG');
UPDATE TGFPRO SET CODVOL = 'SC' WHERE CODVOL IN ('SC/1', 'SA', 'SAC', 'SACO');
UPDATE TGFPRO SET CODVOL = 'CJ' WHERE CODVOL IN ('CJT');
UPDATE TGFPRO SET CODVOL = 'FL' WHERE CODVOL IN ('FLH');
UPDATE TGFPRO SET CODVOL = 'DZ' WHERE CODVOL IN ('DUZIA', 'DZ12');
UPDATE TGFPRO SET CODVOL = 'M2' WHERE CODVOL IN ('M²');
UPDATE TGFPRO SET CODVOL = 'M3' WHERE CODVOL IN ('M³');
UPDATE TGFPRO SET CODVOL = 'PAR' WHERE CODVOL IN ('PARES');
COMMIT;

